/**
 * ADR-0045 §7 Phase 1's per-(region, aquifer) demand feed -- §4a's RTT histogram, aggregated across every account's relays. Deliberately cross-account, unlike every other endpoint in this file; requires the advisor role (see the Advisor permission role), not merely read access to karst control. Audit-logged as karst.demand.regions.view.
 */
export const demandRegions = <ThrowOnError extends boolean = false>(options?: Options<DemandRegionsData, ThrowOnError>): RequestResult<DemandRegionsResponses, DemandRegionsErrors, ThrowOnError> => (options?.client ?? client).get<DemandRegionsResponses, DemandRegionsErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/demand/regions',
    ...options
});

/**
 * ADR-0045 §7 Phase 1's second demand-side input -- §4b's deployment-wide, anonymous anchor-RTT histogram. No node or account identity appears in this response. Requires the advisor role, the same as demandRegions, so that "who can see what the Advisor sees" stays one grant. Audit-logged as karst.demand.anchors.view.
 */
export const demandAnchors = <ThrowOnError extends boolean = false>(options?: Options<DemandAnchorsData, ThrowOnError>): RequestResult<DemandAnchorsResponses, DemandAnchorsErrors, ThrowOnError> => (options?.client ?? client).get<DemandAnchorsResponses, DemandAnchorsErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/demand/anchors',
    ...options
});

/**
 * ADR-0045 §7 Phase 1's "recommended vs actual" view, proxied unchanged from karst-scaler advise's own loopback /recommendations endpoint (KARST_SCALER_ADVISOR_URL) -- the browser never dials karst-scaler directly. Requires the advisor role, the same as demandRegions/ demandAnchors. Precondition-failed (not 404) if KARST_SCALER_ADVISOR_URL is not configured for this deployment.
 */
export const scalerRecommendations = <ThrowOnError extends boolean = false>(options?: Options<ScalerRecommendationsData, ThrowOnError>): RequestResult<ScalerRecommendationsResponses, ScalerRecommendationsErrors, ThrowOnError> => (options?.client ?? client).get<ScalerRecommendationsResponses, ScalerRecommendationsErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/scaler/recommendations',
    ...options
});

/**
 * ADR-0045 §4c's deployment-wide region allowlist (package regionallow). Governs what is projected into every node's netmap as KarstAllowedRegions and fail-closed validation of incoming §4b anchor-RTT demand reports -- a different list from the one karst-scaler's own driver reads to decide where it may actually provision capacity, kept intentionally out of the control plane's trust domain (ADR-0045 §6).
 */
